import { useMemo, useState } from 'react';
import {
  Activity, ArrowRight, CalendarDays, Check, CheckCircle2, ChevronDown, Clock3, CreditCard,
  ExternalLink, FileText, MessageCircle, Plus, Search, Scissors, Settings2, ShieldCheck,
  Tag, Trash2, UserRound, Users, Wallet, X, Save, DoorClosed, Pencil, Pause, Play,
  TrendingDown, TrendingUp, Phone, CalendarCheck2, Printer, Filter
} from 'lucide-react';

const SERVICE_SEED = [
  { id:'s1', name:'Corte', durationMinutes:30, priceCents:5000, active:true },
  { id:'s2', name:'Barba', durationMinutes:30, priceCents:4000, active:true },
  { id:'s3', name:'Barba e Pigmentação', durationMinutes:45, priceCents:6500, active:true },
  { id:'s4', name:'Corte e Barba', durationMinutes:60, priceCents:8500, active:true },
  { id:'s5', name:'Low Fade ou Navalhado', durationMinutes:60, priceCents:6000, active:true },
  { id:'s6', name:'Pézinho', durationMinutes:15, priceCents:2000, active:true },
  { id:'s7', name:'Sobrancelha', durationMinutes:15, priceCents:2000, active:true },
];
const PRO_SEED = [{id:'p1',name:'Felipe',role:'Barbeiro',active:true},{id:'p2',name:'Vitória',role:'Barbeira',active:true}];
const DAYS = ['Domingo','Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','Sexta-feira','Sábado'];
const dateKey = (offset=0) => { const d=new Date(); d.setDate(d.getDate()+offset); return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-'); };
const money = (cents) => new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format((Number(cents)||0)/100);
const dateText = (value) => value ? new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(value+'T12:00:00')) : '—';
const phoneFormat = (value) => {const d=String(value||'').replace(/\D/g,'').slice(0,11);if(d.length<=2)return d?'('+d:'';if(d.length<=6)return '('+d.slice(0,2)+') '+d.slice(2);if(d.length<=10)return '('+d.slice(0,2)+') '+d.slice(2,6)+'-'+d.slice(6);return '('+d.slice(0,2)+') '+d.slice(2,7)+'-'+d.slice(7);};
const endTime = (time,duration) => {const total=Number(time.slice(0,2))*60+Number(time.slice(3,5))+duration;return String(Math.floor(total/60)).padStart(2,'0')+':'+String(total%60).padStart(2,'0');};
const STATUS = {confirmed:'Confirmado',cancelled:'Cancelado',completed:'Concluído',no_show:'Não compareceu'};
const timeSlots = Array.from({length:23},(_,i)=>{const m=9*60+i*30;return String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');});
const SERVICE_PROMOS = [
  {id:'pr1',name:'Combo corte + barba',kind:'combo',startsOn:dateKey(-3),endsOn:dateKey(14),active:true,serviceIds:['s1','s2'],promoPriceCents:7500},
  {id:'pr2',name:'Pézinho especial',kind:'service',startsOn:dateKey(-1),endsOn:dateKey(10),active:true,serviceIds:['s6'],promoPriceCents:1500},
];
const makeGroup = (id,offset,time,customer,phone,serviceIds,status,pro='Felipe',marked=false) => {
  const d=dateKey(offset), services=serviceIds.map((sid)=>SERVICE_SEED.find(s=>s.id===sid)).filter(Boolean);
  let cursor=time;
  const items=services.map((s)=>{const item={id:id+'-'+s.id,serviceName:s.name,professionalName:pro,time:cursor,durationMinutes:s.durationMinutes,priceCents:s.priceCents};cursor=endTime(cursor,s.durationMinutes);return item;});
  return {id:String(id),publicCode:'B67-'+String(1100+id),date:d,status,customer:{name:customer,whatsapp:phone},items,totalPriceCents:items.reduce((sum,x)=>sum+x.priceCents,0),whatsappConfirmationMarkedAt:marked?new Date().toISOString():null};
};
const APPOINTMENT_SEED = [
  makeGroup(1,0,'09:00','Mariana Costa','67999120011',['s1','s2'],'confirmed','Felipe',true),
  makeGroup(2,0,'11:00','Camila Oliveira','67999120022',['s4'],'confirmed','Vitória'),
  makeGroup(3,1,'10:00','Juliana Martins','67999120033',['s3','s6'],'confirmed','Felipe'),
  makeGroup(4,2,'14:00','Bianca Souza','67999120044',['s5'],'confirmed','Vitória'),
  makeGroup(5,-2,'09:30','Paula Nunes','67999120055',['s1'],'completed','Felipe'),
  makeGroup(6,-1,'15:00','Renata Alves','67999120066',['s2','s7'],'no_show','Vitória'),
  makeGroup(7,-4,'13:00','Lívia Rocha','67999120077',['s4'],'cancelled','Felipe'),
];
const CUSTOMER_SEED = [
  {id:'c1',name:'Mariana Costa',whatsapp:'67999120011',createdAt:dateKey(-90),appointmentCount:8,noShowCount:0,lastAppointmentDate:dateKey(0)},
  {id:'c2',name:'Camila Oliveira',whatsapp:'67999120022',createdAt:dateKey(-72),appointmentCount:5,noShowCount:1,lastAppointmentDate:dateKey(0)},
  {id:'c3',name:'Juliana Martins',whatsapp:'67999120033',createdAt:dateKey(-48),appointmentCount:11,noShowCount:0,lastAppointmentDate:dateKey(-2)},
  {id:'c4',name:'Bianca Souza',whatsapp:'67999120044',createdAt:dateKey(-31),appointmentCount:3,noShowCount:2,lastAppointmentDate:dateKey(-9)},
];
const HOUR_SEED = DAYS.map((name,weekday)=>({weekday,name,enabled:weekday>=1,openTime:weekday===1?'13:30':weekday===0?'':'09:00',closeTime:weekday===6?'17:00':weekday===0?'':'20:00',breakStart:'',breakEnd:''}));
const moneyFormat = money;
function Card({children,className=''}) { return <section className={'bb-admin-card '+className}>{children}</section>; }
function CardTitle({kicker,title,action}) { return <div className="bb-admin-card-title"><div><span>{kicker}</span><h3>{title}</h3></div>{action}</div>; }
function Field({label,children}) { return <label className="bb-admin-field"><span>{label}</span>{children}</label>; }
function Count({children}) { return <span className="bb-admin-count">{children}</span>; }
function Toggle({checked,onChange,label}) { return <label className="bb-admin-toggle"><input type="checkbox" checked={checked} onChange={(e)=>onChange(e.target.checked)}/><i/><span>{label}</span></label>; }

export default function BarberAdminShowcase({module,notify=()=>{}}) {
  const [services,setServices]=useState(SERVICE_SEED);
  const [professionals,setProfessionals]=useState(PRO_SEED);
  const [appointments,setAppointments]=useState(APPOINTMENT_SEED);
  const [customers,setCustomers]=useState(CUSTOMER_SEED);
  const [hours,setHours]=useState(HOUR_SEED);
  const [blocks,setBlocks]=useState([{id:'b1',scope:'professional',professionalId:'p2',professionalName:'Vitória',date:dateKey(3),startTime:'14:00',endTime:'16:00',reason:'Compromisso'},{id:'b2',scope:'business',date:dateKey(6),startTime:'',endTime:'',reason:'Folga da barbearia'}]);
  const [promotions,setPromotions]=useState(SERVICE_PROMOS);
  const [entries,setEntries]=useState([
    {id:'f1',direction:'income',description:'Atendimento · Mariana Costa',category:'Serviços',amountCents:8500,movementDate:dateKey(0),paymentMethod:'Pix'},
    {id:'f2',direction:'expense',description:'Compra de produtos',category:'Materiais',amountCents:12900,movementDate:dateKey(-1),paymentMethod:'Cartão'},
    {id:'f3',direction:'income',description:'Corte · Paula Nunes',category:'Serviços',amountCents:5000,movementDate:dateKey(-2),paymentMethod:'Dinheiro'},
  ]);
  const [payables,setPayables]=useState([{id:'p1',description:'Aluguel do ponto',category:'Estrutura',amountCents:90000,dueDate:dateKey(4),status:'pending'},{id:'p2',description:'Reposição de materiais',category:'Materiais',amountCents:18500,dueDate:dateKey(-3),status:'pending'}]);
  const [receipts,setReceipts]=useState([{id:'r1',groupId:'2',publicCode:'B67-1102',customerName:'Camila Oliveira',itemSummary:'Corte e Barba',totalPriceCents:8500,date:dateKey(0),status:'pending'}]);

  if(module==='appointments') return <AppointmentsView {...{appointments,setAppointments,notify}}/>;
  if(module==='clients') return <CustomersView {...{customers,setCustomers,appointments,notify}}/>;
  if(module==='services') return <ServicesView {...{services,setServices,notify}}/>;
  if(module==='professionals') return <ProfessionalsView {...{professionals,setProfessionals,appointments,notify}}/>;
  if(module==='hours') return <HoursView {...{hours,setHours,notify}}/>;
  if(module==='blocks') return <BlocksView {...{blocks,setBlocks,hours,professionals,notify}}/>;
  if(module==='promotions') return <PromotionsView {...{promotions,setPromotions,services,notify}}/>;
  if(module==='finance') return <FinanceView {...{appointments,entries,setEntries,payables,setPayables,receipts,setReceipts,notify}}/>;
  return <OverviewView {...{appointments,services,professionals,promotions,entries}}/>;
}

function OverviewView({appointments,services,professionals,promotions,entries}) {
  const today=dateKey(0), todayGroups=appointments.filter((g)=>g.date===today);
  const confirmed=todayGroups.filter((g)=>g.status==='confirmed').length;
  const completed=todayGroups.filter((g)=>g.status==='completed').length;
  const revenue=todayGroups.filter((g)=>g.status==='confirmed').reduce((sum,g)=>sum+g.totalPriceCents,0);
  return <div className="bb-admin">
    <div className="bb-admin-page-title"><div><span className="bb-kicker">SUA BARBEARIA, EM UM SÓ LUGAR</span><h2>Visão geral.</h2><p>Acompanhe a agenda e mantenha os atendimentos organizados.</p></div><span className="bb-date-chip"><CalendarDays size={15}/>{dateText(today)}</span></div>
    <section className="bb-welcome"><span><Activity size={20}/></span><div><strong>Um novo dia para cuidar de cada detalhe.</strong><p>Consulte seus horários, acompanhe as confirmações e deixe a agenda pronta para receber clientes.</p></div></section>
    <div className="bb-admin-metrics"><article><span>Atendimentos</span><strong>{todayGroups.length}</strong><small>Na data selecionada</small></article><article><span>Confirmados</span><strong>{confirmed}</strong><small>Ocupando a agenda</small></article><article><span>Concluídos</span><strong>{completed}</strong><small>Atendimentos finalizados</small></article><article><span>Valor previsto</span><strong>{money(revenue)}</strong><small>Atendimentos confirmados</small></article></div>
    <div className="bb-overview-grid">
      <Card><CardTitle kicker="AGENDA" title="Atendimentos do dia" action={<Count>{todayGroups.length}</Count>}/>{todayGroups.length?todayGroups.map((group)=><div className="bb-overview-appointment" key={group.id}><span>{group.items[0]?.time}</span><div><strong>{group.customer.name}</strong><small>{group.items.map((i)=>i.serviceName).join(' · ')}</small></div><b>{money(group.totalPriceCents)}</b></div>):<p className="bb-empty">A agenda está tranquila para este dia.</p>}</Card>
      <Card><CardTitle kicker="ACESSO RÁPIDO" title="Organize sua rotina."/><div className="bb-quick-links"><span>Agendamentos · Clientes · Serviços</span><span>Equipe e horários</span><span>Bloqueios da agenda</span><span>Promoções individuais e combos</span><span>Receitas, despesas e contas a pagar</span></div><p className="bb-admin-helper"><ShieldCheck size={14}/> A disponibilidade pública usa os horários, profissionais e bloqueios configurados.</p></Card>
    </div>
    <p className="bb-demo-note"><ShieldCheck size={14}/> Dados fictícios para demonstração. A aplicação real mantém os cadastros e alterações no armazenamento local.</p>
  </div>;
}

function AppointmentsView({appointments,setAppointments,notify}) {
  const [filter,setFilter]=useState('upcoming');
  const [preparedWhatsappId,setPreparedWhatsappId]=useState('');
  const [search,setSearch]=useState('');
  const filtered=appointments.filter((group)=>{
    const text=(group.customer.name+' '+group.customer.whatsapp+' '+group.publicCode+' '+group.items.map((i)=>i.serviceName+' '+i.professionalName).join(' ')).toLowerCase();
    const matches=!search||text.includes(search.toLowerCase())||group.customer.whatsapp.replace(/\D/g,'').includes(search.replace(/\D/g,''));
    const next=group.date>=dateKey(0)&&!['cancelled','no_show'].includes(group.status);
    const pending=group.status==='confirmed'&&!group.whatsappConfirmationMarkedAt;
    return matches&&(filter==='all'||(filter==='upcoming'&&next)||(filter==='pending'&&pending));
  }).sort((a,b)=>(a.date+' '+(a.items[0]?.time||'')).localeCompare(b.date+' '+(b.items[0]?.time||'')));
  return <div className="bb-admin">
    <div className="bb-admin-page-title"><div><span className="bb-kicker">ACOMPANHE SUA ROTINA</span><h2>Agendamentos.</h2><p>Consulte os próximos atendimentos, revise confirmações e atualize o status ao finalizar.</p></div><button className="bb-action-button" onClick={()=>window.print()}><Printer size={15}/> Imprimir agenda</button></div>
    <div className="bb-agenda-toolbar"><div className="bb-segmented">{[['upcoming','Próximos'],['pending','Confirmação pendente'],['all','Todos']].map(([value,label])=><button key={value} className={filter===value?'active':''} onClick={()=>setFilter(value)}>{label}</button>)}</div><label className="bb-search"><Search size={16}/><input value={search} onChange={(e)=>setSearch(e.target.value)} placeholder="Buscar cliente, WhatsApp, serviço ou código"/></label></div>
    <p className="bb-results-count">{filtered.length} {filtered.length===1?'atendimento':'atendimentos'}{filter==='pending'?' aguardando a marcação manual da confirmação via WhatsApp':''}</p>
    <section className="bb-appointment-list">{filtered.length?filtered.map((group)=><article className="bb-admin-card bb-appointment-admin-card" key={group.id}>
      <div className="bb-appointment-date"><strong>{dateText(group.date)}</strong><b>{group.items[0]?.time}</b></div>
      <div className="bb-appointment-details"><div className="bb-appointment-top"><div><strong>{group.customer.name}</strong><small>{phoneFormat(group.customer.whatsapp)} · {group.items.length} {group.items.length===1?'procedimento':'procedimentos'} · Código {group.publicCode}</small></div><b>{money(group.totalPriceCents)}</b></div><span className={'bb-status '+group.status}>{STATUS[group.status]}</span>
      <div className="bb-admin-appointment-items">{group.items.map((item)=><div key={item.id}><strong>{item.time}</strong><span>{item.serviceName}<small>{item.professionalName} · {item.durationMinutes} min</small></span><b>{money(item.priceCents)}</b></div>)}</div>
      {group.status==='confirmed'&&<div className="bb-appointment-actions"><button className="bb-action-button" disabled={Boolean(group.whatsappConfirmationMarkedAt)} onClick={()=>{if(preparedWhatsappId!==group.id){setPreparedWhatsappId(group.id);notify('Mensagem de confirmação preparada. Depois de enviar pelo WhatsApp, volte aqui e marque como enviado.');}else{setAppointments((items)=>items.map((g)=>g.id===group.id?{...g,whatsappConfirmationMarkedAt:new Date().toISOString()}:g));setPreparedWhatsappId('');notify('Confirmação via WhatsApp marcada como enviada.');}}}><MessageCircle size={14}/> {group.whatsappConfirmationMarkedAt?'Confirmação registrada':preparedWhatsappId===group.id?'Marcar como enviado':'Preparar WhatsApp'}</button><label>Status<select value={group.status} onChange={(e)=>setAppointments((items)=>items.map((g)=>g.id===group.id?{...g,status:e.target.value}:g))}><option value="confirmed">Confirmado</option><option value="completed">Concluído</option><option value="cancelled">Cancelado</option><option value="no_show">Não compareceu</option></select></label><button className="bb-text-action" onClick={()=>setAppointments((items)=>items.map((g)=>g.id===group.id?{...g,whatsappConfirmationMarkedAt:new Date().toISOString()}:g))}>Marcar enviado</button></div>}
      </div></article>):<div className="bb-empty-large"><CalendarDays size={24}/><strong>Nenhum agendamento encontrado</strong><p>Ajuste os filtros ou tente outra busca.</p></div>}</section>
    <p className="bb-demo-note"><ShieldCheck size={14}/> Na aplicação real, a confirmação via WhatsApp abre a mensagem pronta e o envio é registrado manualmente depois da confirmação.</p>
  </div>;
}

function CustomersView({customers,setCustomers,appointments,notify}) {
  const [search,setSearch]=useState(''),[showCreate,setShowCreate]=useState(false),[newName,setNewName]=useState(''),[newPhone,setNewPhone]=useState(''),[expanded,setExpanded]=useState('');
  const filtered=customers.filter((c)=>(c.name+' '+c.whatsapp).toLowerCase().includes(search.toLowerCase())||c.whatsapp.replace(/\D/g,'').includes(search.replace(/\D/g,'')));
  function add(e){e.preventDefault();setCustomers((items)=>[{id:'c'+Date.now(),name:newName,whatsapp:newPhone,createdAt:dateKey(0),appointmentCount:0,noShowCount:0,lastAppointmentDate:null},...items]);setNewName('');setNewPhone('');setShowCreate(false);notify('Cliente cadastrado na demonstração.');}
  return <div className="bb-admin">
    <div className="bb-admin-page-title"><div><span className="bb-kicker">CADASTRO E HISTÓRICO</span><h2>Clientes.</h2><p>Pesquise por nome ou WhatsApp e consulte atendimentos anteriores.</p></div><Count>{customers.length} cadastrados</Count></div>
    <Card><CardTitle kicker="NOVO CADASTRO" title="Adicionar cliente" action={<button className="bb-action-button" onClick={()=>setShowCreate((v)=>!v)}>{showCreate?'Fechar':'＋ Adicionar'}</button>}/><p className="bb-admin-helper">Cadastre também clientes que agendam diretamente na barbearia.</p>{showCreate&&<form className="bb-admin-form" onSubmit={add}><Field label="Nome completo"><input value={newName} onChange={(e)=>setNewName(e.target.value)} minLength={2} maxLength={100} required placeholder="Nome do cliente"/></Field><Field label="WhatsApp com DDD"><input value={newPhone} onChange={(e)=>setNewPhone(phoneFormat(e.target.value))} maxLength={16} required placeholder="(67) 99999-9999"/></Field><p>O WhatsApp é usado para localizar cadastros e evitar duplicidades.</p><button className="bb-primary-button">Cadastrar cliente</button></form>}</Card>
    <Card><CardTitle kicker="CADASTROS EXISTENTES" title="Localizar cliente" action={<Count>{filtered.length}</Count>}/><label className="bb-search"><Search size={16}/><input value={search} onChange={(e)=>setSearch(e.target.value)} placeholder="Pesquisar por nome ou telefone"/></label><div className="bb-customer-list">{filtered.map((customer)=>{const history=appointments.filter((a)=>a.customer.name===customer.name);return <article key={customer.id} className="bb-customer-card"><button className="bb-customer-row" onClick={()=>setExpanded(expanded===customer.id?'':customer.id)}><span className="bb-avatar">{customer.name.split(' ').map((x)=>x[0]).slice(0,2).join('')}</span><span><strong>{customer.name}</strong><small>{phoneFormat(customer.whatsapp)}</small></span><em>{customer.appointmentCount} atend. · {customer.noShowCount} faltas</em><ChevronDown size={16}/></button>{expanded===customer.id&&<div className="bb-customer-expanded"><div className="bb-customer-meta"><span>Último agendamento: {dateText(customer.lastAppointmentDate)}</span><span>Cadastro: {dateText(customer.createdAt)}</span></div><Field label="Nome exibido"><input value={customer.name} onChange={(e)=>setCustomers((items)=>items.map((c)=>c.id===customer.id?{...c,name:e.target.value}:c))}/></Field><button className="bb-action-button" onClick={()=>notify('Nome do cadastro atualizado na demonstração.')}><Save size={14}/> Salvar nome</button><h4>Histórico de atendimentos ({history.length})</h4>{history.length?history.map((g)=><div className="bb-history-item" key={g.id}><strong>{dateText(g.date)} · {g.items[0]?.time}</strong><span>{g.items.map((i)=>i.serviceName+' ('+i.professionalName+')').join(' · ')}</span><small>{g.publicCode} · {STATUS[g.status]}</small><b>{money(g.totalPriceCents)}</b></div>):<p>Nenhum atendimento anterior.</p>}</div>}</article>;})}</div></Card>
    <p className="bb-demo-note"><ShieldCheck size={14}/> O P15 mantém histórico de serviços, profissionais, horários, códigos, valores e faltas de cada cliente.</p>
  </div>;
}

function ServicesView({services,setServices,notify}) {
  const [showCreate,setShowCreate]=useState(false),[name,setName]=useState(''),[duration,setDuration]=useState('30'),[price,setPrice]=useState('50');
  function add(e){e.preventDefault();setServices((items)=>[...items,{id:'s'+Date.now(),name,durationMinutes:Number(duration),priceCents:Math.round(Number(price)*100),active:true}]);setName('');setShowCreate(false);notify('Serviço criado na demonstração.');}
  return <div className="bb-admin">
    <div className="bb-admin-page-title"><div><span className="bb-kicker">CATÁLOGO DA BARBEARIA</span><h2>Serviços e preços.</h2><p>Cadastre procedimentos, defina duração e preço e controle o que fica disponível para agendamento.</p></div><Count>{services.filter(s=>s.active).length} ativos</Count></div>
    <div className="bb-two-columns"><Card><CardTitle kicker="NOVO SERVIÇO" title="Cadastrar serviço" action={<button className="bb-action-button" onClick={()=>setShowCreate((v)=>!v)}>{showCreate?'Fechar':'＋ Adicionar'}</button>}/>{showCreate&&<form className="bb-admin-form" onSubmit={add}><Field label="Nome do serviço"><input value={name} onChange={(e)=>setName(e.target.value)} minLength={2} maxLength={120} required placeholder="Ex.: Corte infantil"/></Field><div className="bb-form-grid"><Field label="Duração"><select value={duration} onChange={(e)=>setDuration(e.target.value)}>{[15,30,45,60,90,120].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Preço (R$)"><input type="number" value={price} onChange={(e)=>setPrice(e.target.value)} min="0" step="0.01"/></Field></div><button className="bb-primary-button">Cadastrar serviço</button></form>}</Card><Card><CardTitle kicker="CATÁLOGO" title="Serviços cadastrados"/></Card></div>
    <div className="bb-service-admin-list">{services.map((service)=><Card key={service.id}><div className="bb-service-admin-row"><span className="bb-service-icon"><Scissors size={18}/></span><div><small>{service.durationMinutes} minutos</small><strong>{service.name}</strong></div><b>{money(service.priceCents)}</b><Toggle checked={service.active} onChange={(active)=>setServices((items)=>items.map((s)=>s.id===service.id?{...s,active}:s))} label={service.active?'Ativo':'Inativo'}/></div><div className="bb-form-grid"><Field label="Nome"><input value={service.name} onChange={(e)=>setServices((items)=>items.map((s)=>s.id===service.id?{...s,name:e.target.value}:s))}/></Field><Field label="Duração (min)"><select value={service.durationMinutes} onChange={(e)=>setServices((items)=>items.map((s)=>s.id===service.id?{...s,durationMinutes:Number(e.target.value)}:s))}>{[15,30,45,60,90,120].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Preço (R$)"><input type="number" step="0.01" value={(service.priceCents/100).toFixed(2)} onChange={(e)=>setServices((items)=>items.map((s)=>s.id===service.id?{...s,priceCents:Math.round(Number(e.target.value)*100)}:s))}/></Field></div><button className="bb-action-button" onClick={()=>notify('Alterações do serviço salvas na demonstração.')}><Save size={14}/> Salvar alterações</button></Card>)}</div>
  </div>;
}

function ProfessionalsView({professionals,setProfessionals,appointments,notify}) {
  const [showCreate,setShowCreate]=useState(false),[name,setName]=useState(''),[role,setRole]=useState('Barbeiro');
  function add(e){e.preventDefault();setProfessionals((items)=>[...items,{id:'p'+Date.now(),name,role,active:true}]);setName('');setShowCreate(false);notify('Profissional cadastrado na demonstração.');}
  return <div className="bb-admin">
    <div className="bb-admin-page-title"><div><span className="bb-kicker">EQUIPE DA BARBEARIA</span><h2>Profissionais.</h2><p>Gerencie a equipe que pode receber procedimentos e aparecer na escolha do cliente.</p></div><Count>{professionals.filter(p=>p.active).length} ativos</Count></div>
    <div className="bb-two-columns"><Card><CardTitle kicker="NOVA PESSOA" title="Cadastrar profissional" action={<button className="bb-action-button" onClick={()=>setShowCreate((v)=>!v)}>{showCreate?'Fechar':'＋ Adicionar'}</button>}/>{showCreate&&<form className="bb-admin-form" onSubmit={add}><Field label="Nome"><input value={name} onChange={(e)=>setName(e.target.value)} minLength={2} required/></Field><Field label="Função"><input value={role} onChange={(e)=>setRole(e.target.value)} minLength={2} required/></Field><button className="bb-primary-button">Cadastrar profissional</button></form>}</Card><Card><CardTitle kicker="EQUIPE" title="Profissionais cadastrados" action={<Count>{professionals.length}</Count>}/>{professionals.map((p)=><div className="bb-professional-detail" key={p.id}><div className="bb-professional-row"><span className="bb-avatar">{p.name.split(' ').map((x)=>x[0]).join('').slice(0,2)}</span><div><strong>{p.name}</strong><small>{p.role}</small></div><Toggle checked={p.active} onChange={(active)=>setProfessionals((items)=>items.map((q)=>q.id===p.id?{...q,active}:q))} label={p.active?'Ativo':'Inativo'}/></div><div className="bb-professional-edit"><Field label="Nome"><input value={p.name} onChange={(e)=>setProfessionals((items)=>items.map((q)=>q.id===p.id?{...q,name:e.target.value}:q))}/></Field><Field label="Função"><input value={p.role} onChange={(e)=>setProfessionals((items)=>items.map((q)=>q.id===p.id?{...q,role:e.target.value}:q))}/></Field><button className="bb-action-button" onClick={()=>notify('Cadastro do profissional atualizado na demonstração.')}><Save size={13}/> Salvar alterações</button></div></div>)}</Card></div>
    <Card><CardTitle kicker="HISTÓRICO" title="Vínculo de atendimentos"/><p className="bb-admin-helper">Desativar um profissional não apaga seus atendimentos anteriores. Os registros históricos continuam identificando quem realizou cada procedimento.</p>{appointments.slice(0,4).map((g)=><div className="bb-overview-appointment" key={g.id}><span>{dateText(g.date)}</span><div><strong>{g.customer.name}</strong><small>{g.items.map((i)=>i.professionalName).join(' · ')}</small></div></div>)}</Card>
  </div>;
}

function HoursView({hours,setHours,notify}) {
  return <div className="bb-admin"><div className="bb-admin-page-title"><div><span className="bb-kicker">DISPONIBILIDADE</span><h2>Funcionamento semanal.</h2><p>Configure abertura, fechamento e intervalos de cada dia.</p></div></div><p className="bb-admin-notice"><Clock3 size={16}/> Os inícios de agendamento seguem a grade de 30 minutos e respeitam a duração real dos serviços.</p><div className="bb-hours-grid">{hours.map((day)=><Card key={day.weekday} className={!day.enabled?'is-closed':''}><div className="bb-hours-heading"><div><strong>{day.name}</strong><small>{day.enabled?day.openTime+' — '+day.closeTime:'Fechado'}</small></div><Toggle checked={day.enabled} onChange={(enabled)=>setHours((items)=>items.map((d)=>d.weekday===day.weekday?{...d,enabled,openTime:enabled?(d.openTime||'09:00'):'',closeTime:enabled?(d.closeTime||'18:00'):''}:d))} label={day.enabled?'Aberto':'Fechado'}/></div><div className="bb-form-grid"><Field label="Abertura"><input type="time" step="1800" value={day.openTime} disabled={!day.enabled} onChange={(e)=>setHours((items)=>items.map((d)=>d.weekday===day.weekday?{...d,openTime:e.target.value}:d))}/></Field><Field label="Fechamento"><input type="time" step="1800" value={day.closeTime} disabled={!day.enabled} onChange={(e)=>setHours((items)=>items.map((d)=>d.weekday===day.weekday?{...d,closeTime:e.target.value}:d))}/></Field><Field label="Início da pausa"><input type="time" step="1800" value={day.breakStart} disabled={!day.enabled} onChange={(e)=>setHours((items)=>items.map((d)=>d.weekday===day.weekday?{...d,breakStart:e.target.value}:d))}/></Field><Field label="Fim da pausa"><input type="time" step="1800" value={day.breakEnd} disabled={!day.enabled} onChange={(e)=>setHours((items)=>items.map((d)=>d.weekday===day.weekday?{...d,breakEnd:e.target.value}:d))}/></Field></div><div className="bb-hours-footer"><button className="bb-text-action" disabled={!day.enabled||(!day.breakStart&&!day.breakEnd)} onClick={()=>setHours((items)=>items.map((d)=>d.weekday===day.weekday?{...d,breakStart:'',breakEnd:''}:d))}>Remover intervalo</button><button className="bb-action-button" onClick={()=>notify('Horário de '+day.name+' salvo na demonstração.')}><Save size={14}/> Salvar dia</button></div></Card>)}</div></div>;
}

function BlocksView({blocks,setBlocks,hours,professionals,notify}) {
  const [date,setDate]=useState(dateKey(2)),[scope,setScope]=useState('professional'),[pro,setPro]=useState('p1'),[allDay,setAllDay]=useState(false),[start,setStart]=useState('13:00'),[end,setEnd]=useState('14:00'),[reason,setReason]=useState('');
  const daily=blocks.filter((b)=>b.date===date);
  function add(e){e.preventDefault();if(!(scope==='business'&&allDay)&&(!start||!end||start>=end)){notify('Confira o intervalo do bloqueio.');return;}const professional=professionals.find(p=>p.id===pro);setBlocks((items)=>[{id:'b'+Date.now(),scope,professionalId:scope==='professional'?pro:undefined,professionalName:scope==='professional'?professional?.name:'Toda a barbearia',date,startTime:scope==='business'&&allDay?'':start,endTime:scope==='business'&&allDay?'':end,reason},...items]);setReason('');notify('Bloqueio demonstrativo criado.');}
  return <div className="bb-admin"><div className="bb-admin-page-title"><div><span className="bb-kicker">INDISPONIBILIDADE</span><h2>Bloqueios da agenda.</h2><p>Bloqueie períodos de um profissional ou de toda a barbearia.</p></div></div><div className="bb-two-columns"><Card><CardTitle kicker="NOVA INDISPONIBILIDADE" title="Criar bloqueio"/><form className="bb-admin-form" onSubmit={add}><Field label="Data"><input type="date" min={dateKey(0)} value={date} onChange={(e)=>setDate(e.target.value)} required/></Field><Field label="Aplicar a"><select value={scope} onChange={(e)=>{setScope(e.target.value);if(e.target.value==='professional')setAllDay(false);}}><option value="professional">Um profissional</option><option value="business">Toda a barbearia</option></select></Field>{scope==='professional'&&<Field label="Profissional"><select value={pro} onChange={(e)=>setPro(e.target.value)}>{professionals.filter(p=>p.active).map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field>}{scope==='business'&&<Toggle checked={allDay} onChange={setAllDay} label="Bloquear o dia inteiro"/>}{!(scope==='business'&&allDay)&&<div className="bb-form-grid"><Field label="Início"><input type="time" step="1800" value={start} onChange={(e)=>setStart(e.target.value)} required/></Field><Field label="Fim"><input type="time" step="1800" value={end} onChange={(e)=>setEnd(e.target.value)} required/></Field></div>}<Field label="Motivo (opcional)"><input maxLength={160} value={reason} onChange={(e)=>setReason(e.target.value)} placeholder="Ex.: compromisso, manutenção"/></Field><button className="bb-primary-button"><Plus size={15}/> Criar bloqueio</button></form><p className="bb-admin-helper">No P15 real, conflitos com atendimentos confirmados são recusados.</p></Card><Card><CardTitle kicker="AGENDA" title="Bloqueios do dia" action={<Count>{daily.length}</Count>}/><Field label="Consultar data"><input type="date" min={dateKey(0)} value={date} onChange={(e)=>setDate(e.target.value)}/></Field>{daily.length?daily.map((block)=><div className="bb-block-row" key={block.id}><div><strong>{block.startTime&&block.endTime?block.startTime+' — '+block.endTime:'Dia inteiro'}</strong><small>{block.scope==='business'?'Toda a barbearia':block.professionalName}{block.reason?' · '+block.reason:''}</small></div><button className="bb-text-action danger" onClick={()=>setBlocks((items)=>items.filter((b)=>b.id!==block.id))}>Remover</button></div>):<p className="bb-empty">Nenhum bloqueio para esta data.</p>}</Card></div></div>;
}

function PromotionsView({promotions,setPromotions,services,notify}) {
  const [showForm,setShowForm]=useState(false),[editing,setEditing]=useState(null),[name,setName]=useState(''),[kind,setKind]=useState('service'),[start,setStart]=useState(dateKey(0)),[end,setEnd]=useState(dateKey(7)),[selectedIds,setSelectedIds]=useState([]),[price,setPrice]=useState(''),[active,setActive]=useState(true),[filter,setFilter]=useState('all');
  const selectable=services.filter(s=>s.active);
  const regular=selectedIds.reduce((sum,id)=>sum+(services.find(s=>s.id===id)?.priceCents||0),0);
  const discount=regular-Math.round(Number(price||0)*100);
  function reset(){setShowForm(false);setEditing(null);setName('');setKind('service');setStart(dateKey(0));setEnd(dateKey(7));setSelectedIds([]);setPrice('');setActive(true);}
  function edit(p){setEditing(p.id);setName(p.name);setKind(p.kind);setStart(p.startsOn);setEnd(p.endsOn);setSelectedIds([...p.serviceIds]);setPrice((p.promoPriceCents/100).toFixed(2));setActive(p.active);setShowForm(true);}
  function toggle(id,checked){setSelectedIds((ids)=>{if(checked){if(kind==='service')return [id];if(ids.length>=6)return ids;return [...ids,id];}return ids.filter(x=>x!==id);});}
  function save(e){e.preventDefault();const valid=kind==='service'?selectedIds.length===1:selectedIds.length>=2&&selectedIds.length<=6;if(!valid||Number(price)<=0||Math.round(Number(price)*100)>=regular||start>end){notify('Confira os serviços, período e preço promocional.');return;}const promo={id:editing||'pr'+Date.now(),name,kind,startsOn:start,endsOn:end,active,serviceIds:selectedIds,promoPriceCents:Math.round(Number(price)*100)};setPromotions((items)=>editing?items.map(x=>x.id===editing?promo:x):[promo,...items]);reset();notify('Promoção salva na demonstração.');}
  const state=(p)=>!p.active?'paused':p.endsOn<dateKey(0)?'ended':p.startsOn>dateKey(0)?'scheduled':'active';
  const filtered=promotions.filter(p=>filter==='all'||state(p)===filter);
  return <div className="bb-admin"><div className="bb-admin-page-title"><div><span className="bb-kicker">OFERTAS DA BARBEARIA</span><h2>Promoções.</h2><p>Crie ofertas para um serviço individual ou combos de 2 a 6 serviços, sem alterar o catálogo normal.</p></div></div><details className="bb-info"><summary>Como funcionam os combos</summary><p>O desconto é aplicado quando todos os serviços do combo estiverem no mesmo atendimento e a data estiver dentro da validade.</p></details><Card><CardTitle kicker={editing?'EDITAR OFERTA':'NOVA OFERTA'} title={editing?'Editar promoção':'Criar promoção'} action={<button className="bb-action-button" onClick={()=>showForm?reset():setShowForm(true)}>{showForm?'Fechar formulário':'＋ Nova promoção'}</button>}/>{showForm&&<form className="bb-admin-form" onSubmit={save}><Field label="Nome da promoção"><input value={name} onChange={(e)=>setName(e.target.value)} minLength={2} maxLength={100} required placeholder="Ex.: Combo corte + barba"/></Field><Field label="Tipo de oferta"><select value={kind} onChange={(e)=>{setKind(e.target.value);if(e.target.value==='service'&&selectedIds.length>1)setSelectedIds(selectedIds.slice(0,1));}}><option value="service">Promoção de um serviço</option><option value="combo">Combo de serviços</option></select></Field><div className="bb-form-grid"><Field label="Início da validade"><input type="date" value={start} onChange={(e)=>setStart(e.target.value)} required/></Field><Field label="Fim da validade"><input type="date" min={start} value={end} onChange={(e)=>setEnd(e.target.value)} required/></Field></div><div className="bb-promo-choices"><strong>{kind==='service'?'Escolha um serviço':'Escolha 2 a 6 serviços'}</strong>{selectable.map((service)=><label key={service.id}><input type={kind==='service'?'radio':'checkbox'} checked={selectedIds.includes(service.id)} onChange={(e)=>toggle(service.id,e.target.checked)}/><span>{service.name}<small>{service.durationMinutes} min · {money(service.priceCents)}</small></span></label>)}</div><div className="bb-promo-price"><span>Valor normal: <strong>{money(regular)}</strong></span><span>Desconto calculado: <strong>{money(discount)}</strong></span></div><Field label="Preço promocional (R$)"><input type="number" min="0.01" step="0.01" value={price} onChange={(e)=>setPrice(e.target.value)} required/></Field><Toggle checked={active} onChange={setActive} label="Promoção ativa"/><div className="bb-form-actions"><button type="button" className="bb-action-button" onClick={reset}>Cancelar</button><button type="submit" className="bb-primary-button">{editing?'Salvar alterações':'Criar promoção'}</button></div></form>}</Card><Card><CardTitle kicker="CATÁLOGO DE OFERTAS" title="Promoções cadastradas" action={<Count>{filtered.length}</Count>}/><label className="bb-filter-select">Filtrar por status<select value={filter} onChange={(e)=>setFilter(e.target.value)}><option value="all">Todas</option><option value="active">Ativas</option><option value="scheduled">Programadas</option><option value="ended">Encerradas</option><option value="paused">Pausadas</option></select></label><div className="bb-promotion-admin-list">{filtered.map((p)=>{const full=p.serviceIds.reduce((sum,id)=>sum+(services.find(s=>s.id===id)?.priceCents||0),0);const current=state(p);return <article key={p.id} className="bb-admin-promotion-card"><div><span>{p.kind==='service'?'SERVIÇO INDIVIDUAL':'COMBO'}</span><em className={current}>{current==='active'?'Ativa':current==='scheduled'?'Programada':current==='ended'?'Encerrada':'Pausada'}</em></div><h4>{p.name}</h4><p>{p.serviceIds.map(id=>services.find(s=>s.id===id)?.name).join(' + ')}</p><small>{dateText(p.startsOn)} — {dateText(p.endsOn)}</small><div className="bb-promotion-price-line"><s>{money(full)}</s><strong>{money(p.promoPriceCents)}</strong><b>Economize {money(full-p.promoPriceCents)}</b></div><div className="bb-form-actions"><button className="bb-action-button" onClick={()=>edit(p)}><Pencil size={13}/> Editar</button>{current!=='ended'&&<button className="bb-action-button" onClick={()=>setPromotions((items)=>items.map(x=>x.id===p.id?{...x,active:!x.active}:x))}>{p.active?<Pause size={13}/>:<Play size={13}/>} {p.active?'Pausar':'Ativar'}</button>}</div></article>;})}</div></Card></div>;
}

function FinanceView({appointments,entries,setEntries,payables,setPayables,receipts,setReceipts,notify}) {
  const [month,setMonth]=useState(dateKey(0).slice(0,7)),[showReceipts,setShowReceipts]=useState(false),[showEntries,setShowEntries]=useState(false),[showPayables,setShowPayables]=useState(false),[entryForm,setEntryForm]=useState(false),[payableForm,setPayableForm]=useState(false);
  const [direction,setDirection]=useState('income'),[description,setDescription]=useState(''),[category,setCategory]=useState('Atendimento'),[amount,setAmount]=useState(''),[movementDate,setMovementDate]=useState(dateKey(0)),[method,setMethod]=useState('Pix');
  const [payableDescription,setPayableDescription]=useState(''),[payableCategory,setPayableCategory]=useState('Despesas da barbearia'),[payableAmount,setPayableAmount]=useState(''),[due,setDue]=useState(dateKey(7));
  const [receiptMethod,setReceiptMethod]=useState({});
  const monthEntries=entries.filter(e=>e.movementDate.startsWith(month));
  const incoming=monthEntries.filter(e=>e.direction==='income').reduce((sum,e)=>sum+e.amountCents,0);
  const outgoing=monthEntries.filter(e=>e.direction==='expense').reduce((sum,e)=>sum+e.amountCents,0);
  const open=payables.filter(p=>p.status==='pending');
  const pendingReceipts=receipts.filter(r=>r.status==='pending');
  function addEntry(e){e.preventDefault();const cents=Math.round(Number(amount.replace(',','.'))*100);if(!description.trim()||cents<=0)return;setEntries((items)=>[{id:'f'+Date.now(),direction,description,category,amountCents:cents,movementDate,paymentMethod:method},...items]);setDescription('');setAmount('');setEntryForm(false);notify('Movimentação registrada no financeiro demonstrativo.');}
  function addPayable(e){e.preventDefault();const cents=Math.round(Number(payableAmount.replace(',','.'))*100);if(!payableDescription.trim()||cents<=0)return;setPayables((items)=>[{id:'p'+Date.now(),description:payableDescription,category:payableCategory,amountCents:cents,dueDate:due,status:'pending'},...items]);setPayableDescription('');setPayableAmount('');setPayableForm(false);notify('Conta a pagar cadastrada na demonstração.');}
  function pay(item){if(item.status==='paid')return;setPayables((items)=>items.map(p=>p.id===item.id?{...p,status:'paid'}:p));setEntries((items)=>[{id:'e'+Date.now(),direction:'expense',description:item.description,category:item.category,amountCents:item.amountCents,movementDate:dateKey(0),paymentMethod:'Não informado',sourceType:'payable_payment'},...items]);notify('Pagamento registrado como saída do caixa.');}
  function removeEntry(entry){if(entry.sourceType&&entry.sourceType!=='manual')return;if(!window.confirm('Excluir a movimentação manual “'+entry.description+'”?'))return;setEntries((items)=>items.filter((item)=>item.id!==entry.id));notify('Movimentação manual removida.');}
  function removePayable(payable){if(payable.status!=='pending')return;if(!window.confirm('Excluir a conta “'+payable.description+'”?'))return;setPayables((items)=>items.filter((item)=>item.id!==payable.id));notify('Conta a pagar removida.');}
  function receive(item){setReceipts((items)=>items.map(x=>x.id===item.id?{...x,status:'received'}:x));setEntries((items)=>[{id:'e'+Date.now(),direction:'income',description:'Atendimento · '+item.customerName,category:'Serviços',amountCents:item.totalPriceCents,movementDate:dateKey(0),paymentMethod:receiptMethod[item.id]||'Pix'},...items]);notify('Recebimento confirmado e entrada registrada uma única vez.');}
  return <div className="bb-admin"><div className="bb-admin-page-title"><div><span className="bb-kicker">CONTROLE DE CAIXA</span><h2>Financeiro.</h2><p>Acompanhe entradas, saídas, valores a receber e contas a pagar.</p></div><Field label="Mês de referência"><input type="month" value={month} onChange={(e)=>setMonth(e.target.value)}/></Field></div><p className="bb-admin-notice"><ShieldCheck size={15}/> Controle sem integração bancária: pagamentos só entram no caixa após confirmação manual.</p><div className="bb-finance-metrics"><article><span>Entradas do mês</span><strong>{money(incoming)}</strong><small>{monthEntries.filter(e=>e.direction==='income').length} movimentações</small></article><article><span>Saídas do mês</span><strong>{money(outgoing)}</strong><small>{monthEntries.filter(e=>e.direction==='expense').length} movimentações</small></article><article><span>Valores a receber</span><strong>{money(pendingReceipts.reduce((s,x)=>s+x.totalPriceCents,0))}</strong><small>{pendingReceipts.length} atendimentos</small></article><article><span>Contas a pagar</span><strong>{money(open.reduce((s,x)=>s+x.amountCents,0))}</strong><small>{open.length} pendentes</small></article><article className="balance"><span>Resultado do mês</span><strong>{money(incoming-outgoing)}</strong><small>Entradas menos saídas registradas</small></article></div>
    <Card><CardTitle kicker="ATENDIMENTOS FINALIZADOS" title="Valores a receber" action={<button className="bb-action-button" onClick={()=>setShowReceipts(v=>!v)}>{showReceipts?'Ocultar':'Ver atendimentos'} ({pendingReceipts.length})</button>}/><p className="bb-admin-helper">O horário previsto ou a conclusão tornam o atendimento elegível. Registre o pagamento só depois de recebê-lo.</p>{showReceipts&&pendingReceipts.map((item)=><article className="bb-finance-receipt" key={item.id}><div><strong>{item.customerName}</strong><small>{item.itemSummary} · Código {item.publicCode} · {dateText(item.date)}</small><b>{money(item.totalPriceCents)}</b></div><Field label="Forma de recebimento"><select value={receiptMethod[item.id]||'Pix'} onChange={(e)=>setReceiptMethod((v)=>({...v,[item.id]:e.target.value}))}>{['Pix','Dinheiro','Cartão','Transferência','Não informado','Outro'].map(x=><option key={x}>{x}</option>)}</select></Field><button className="bb-primary-button" onClick={()=>receive(item)}><Check size={14}/> Confirmar recebimento</button></article>)}</Card>
    <div className="bb-two-columns"><Card><CardTitle kicker="MOVIMENTAÇÕES" title="Registrar entrada ou saída" action={<button className="bb-action-button" onClick={()=>setEntryForm(v=>!v)}>{entryForm?'Fechar':'+ Nova movimentação'}</button>}/>{entryForm&&<form className="bb-admin-form" onSubmit={addEntry}><Field label="Tipo"><select value={direction} onChange={(e)=>setDirection(e.target.value)}><option value="income">Entrada de dinheiro</option><option value="expense">Saída de dinheiro</option></select></Field><Field label="Descrição"><input value={description} onChange={(e)=>setDescription(e.target.value)} minLength={2} required/></Field><div className="bb-form-grid"><Field label="Categoria"><input value={category} onChange={(e)=>setCategory(e.target.value)}/></Field><Field label="Valor (R$)"><input value={amount} onChange={(e)=>setAmount(e.target.value)} inputMode="decimal" required/></Field></div><div className="bb-form-grid"><Field label="Data"><input type="date" value={movementDate} max={dateKey(0)} onChange={(e)=>setMovementDate(e.target.value)}/></Field><Field label="Forma de pagamento"><select value={method} onChange={(e)=>setMethod(e.target.value)}>{['Pix','Dinheiro','Cartão','Transferência','Não informado','Outro'].map(x=><option key={x}>{x}</option>)}</select></Field></div><button className="bb-primary-button">Registrar movimentação</button></form>}</Card>
    <Card><CardTitle kicker="ORGANIZAÇÃO" title="Contas a pagar" action={<Count>{payables.length}</Count>}/><button className="bb-action-button" onClick={()=>setPayableForm(v=>!v)}>{payableForm?'Fechar':'＋ Cadastrar conta'}</button>{payableForm&&<form className="bb-admin-form" onSubmit={addPayable}><Field label="Descrição"><input value={payableDescription} onChange={(e)=>setPayableDescription(e.target.value)} required/></Field><div className="bb-form-grid"><Field label="Categoria"><input value={payableCategory} onChange={(e)=>setPayableCategory(e.target.value)}/></Field><Field label="Valor (R$)"><input value={payableAmount} onChange={(e)=>setPayableAmount(e.target.value)} inputMode="decimal" required/></Field></div><Field label="Vencimento"><input type="date" value={due} onChange={(e)=>setDue(e.target.value)}/></Field><button className="bb-primary-button">Cadastrar conta</button></form>}<button className="bb-action-button" onClick={()=>setShowPayables(v=>!v)}>{showPayables?'Ocultar':'Ver contas'} ({payables.length})</button>{showPayables&&payables.map((p)=><div className="bb-payable-row" key={p.id}><div><strong>{p.description}</strong><small>{p.category} · {dateText(p.dueDate)}</small><em>{p.status==='paid'?'Paga':p.dueDate<dateKey(0)?'Vencida':'Em aberto'}</em></div><b>{money(p.amountCents)}</b>{p.status==='pending'&&<div className="bb-payable-actions"><button className="bb-text-action" onClick={()=>pay(p)}>Marcar paga</button><button className="bb-text-action danger" onClick={()=>removePayable(p)}>Excluir</button></div>}</div>)}</Card></div>
    <Card><CardTitle kicker="RESUMO DE CAIXA" title={'Movimentações de '+month.split('-').reverse().join('/') } action={<button className="bb-action-button" onClick={()=>setShowEntries(v=>!v)}>{showEntries?'Ocultar':'Ver todas'} ({monthEntries.length})</button>}/>{(showEntries?monthEntries:monthEntries.slice(0,5)).map((entry)=><div className="bb-entry-row" key={entry.id}><span className={entry.direction}>{entry.direction==='income'?<TrendingUp size={15}/>:<TrendingDown size={15}/>}</span><div><strong>{entry.description}</strong><small>{entry.category} · {dateText(entry.movementDate)} · {entry.paymentMethod}</small></div><b className={entry.direction}>{entry.direction==='income'?'+':'−'} {money(entry.amountCents)}</b>{(!entry.sourceType||entry.sourceType==='manual')&&<button className="bb-text-action danger" onClick={()=>removeEntry(entry)}>Excluir</button>}</div>)}</Card></div>;
}

function OrdersView({orders,setOrders,products,setProducts,notify}) {
  const [sessionOpen,setSessionOpen]=useState(true),[sessionNo,setSessionNo]=useState(1),[nextNumber,setNextNumber]=useState(4),[attendanceDate,setAttendanceDate]=useState(dateKey(0)),[formOpen,setFormOpen]=useState(false),[customer,setCustomer]=useState('Balcão'),[draft,setDraft]=useState([{id:1,productId:'pr1',quantity:'1'}]),[search,setSearch]=useState(''),[scope,setScope]=useState('session'),[paymentId,setPaymentId]=useState(''),[paymentDate,setPaymentDate]=useState(dateKey(0)),[paymentMethod,setPaymentMethod]=useState('Pix');
  const sessionOrders=orders.filter(o=>o.sessionNo===sessionNo),activeOrders=sessionOrders.filter(o=>!['Entregue','Cancelado'].includes(o.status)),shown=(scope==='all'?orders:sessionOrders).filter(o=>(o.number+' '+o.customer+' '+o.items).toLowerCase().includes(search.toLowerCase()));
  const sellable=products.filter(p=>p.sellable);
  function startSession(){setSessionNo(v=>v+1);setNextNumber(1);setAttendanceDate(dateKey(0));setOrders((items)=>items);setSessionOpen(true);notify('Atendimento iniciado. A numeração dos pedidos começou em 001.');}
  function closeSession(){if(activeOrders.length){notify('Finalize ou cancele os pedidos em andamento antes de encerrar.');return;}setSessionOpen(false);setFormOpen(false);notify('Atendimento encerrado. Novos pedidos estão bloqueados.');}
  function newDraft(){setCustomer('Balcão');setDraft([{id:1,productId:'',quantity:'1'}]);setFormOpen(true);}
  function create(e){e.preventDefault();if(!sessionOpen){notify('Inicie o atendimento antes de registrar pedidos.');return;}const rows=draft.map(row=>({...row,product:sellable.find(p=>p.id===row.productId),qty:Number(row.quantity)}));if(rows.some(r=>!r.product||!Number.isFinite(r.qty)||r.qty<=0||((r.product.unit==='un'||r.product.unit==='porcao')&&!Number.isInteger(r.qty)))){notify('Confira produto e quantidade. Unidade e porção exigem quantidade inteira.');return;}for(const row of rows){if(row.product.stockTracked&&row.product.stock<row.qty){notify('Estoque insuficiente para '+row.product.name+'.');return;}}const total=rows.reduce((s,r)=>s+Math.round(r.product.price*100*r.qty),0);let updated=products.map(p=>{const row=rows.find(r=>r.product.id===p.id);return row&&p.stockTracked?{...p,stock:p.stock-row.qty}:p;});setProducts(updated);setOrders(items=>[{id:'o'+Date.now(),number:nextNumber,sessionNo,customer:customer||'Balcão',items:rows.map(r=>r.qty+'x '+r.product.name).join(', '),total,status:'Recebido',paymentStatus:'unpaid',created:'Agora',businessDate:attendanceDate,itemRecords:rows.map(r=>({productId:r.product.id,quantity:r.qty}))},...items]);setNextNumber(v=>v+1);setFormOpen(false);notify('Pedido #'+String(nextNumber).padStart(3,'0')+' registrado. Baixa de estoque aplicada aos itens controlados.');}
  function changeStatus(order){const next=order.status==='Recebido'?'Em preparo':order.status==='Em preparo'?'Pronto':order.status==='Pronto'?'Entregue':null;if(!next)return;setOrders(items=>items.map(o=>o.id===order.id?{...o,status:next}:o));notify('Pedido atualizado para '+next.toLowerCase()+'.');}
  function cancel(order){if(order.paymentStatus==='paid'){notify('Pedido pago não pode ser cancelado.');return;}setProducts(items=>items.map(p=>{const line=order.itemRecords.find(i=>i.productId===p.id);return line&&p.stockTracked?{...p,stock:p.stock+line.quantity}:p;}));setOrders(items=>items.map(o=>o.id===order.id?{...o,status:'Cancelado'}:o));notify('Pedido cancelado e estoque devolvido.');}
  function pay(order,e){e.preventDefault();setOrders(items=>items.map(o=>o.id===order.id?{...o,paymentStatus:'paid',paymentMethod,paymentDate}:o));setPaymentId('');notify('Pagamento registrado. A entrada foi vinculada ao pedido.');}
  return <div className="burger-demo">
    <div className="burger-page-heading"><div><span>OPERAÇÃO DO ESTABELECIMENTO</span><h2>Pedidos.</h2><p>Organize o preparo e acompanhe as retiradas durante o expediente.</p></div><div className="burger-session-actions">{sessionOpen?<button onClick={closeSession}>Encerrar atendimento</button>:<button onClick={startSession}>Iniciar atendimento</button>}</div></div>
    <div className={'burger-session-banner '+(sessionOpen?'open':'closed')}><span>{sessionOpen?'ATENDIMENTO ABERTO':'ATENDIMENTO ENCERRADO'}</span><strong>{sessionOpen?'Próximo pedido #'+String(nextNumber).padStart(3,'0'):'Novos pedidos estão bloqueados até abrir um novo atendimento.'}</strong>{sessionOpen&&<small>Iniciado em {dateText(attendanceDate)} · {activeOrders.length} pedido(s) em andamento</small>}</div>
    <Card><CardTitle kicker="PEDIDOS" title="Acompanhe o fluxo" action={<button className="bb-action-button" onClick={()=>setScope(v=>v==='session'?'all':'session')}>{scope==='session'?'Ver histórico completo':'Ver atendimento atual'}</button>}/><div className="bb-agenda-toolbar"><label className="bb-search"><Search size={16}/><input value={search} onChange={(e)=>setSearch(e.target.value)} placeholder="Buscar número ou cliente"/></label>{sessionOpen&&<button className="bb-primary-button" onClick={newDraft}>＋ Novo pedido</button>}</div>{formOpen&&<form className="bb-admin-form" onSubmit={create}><Field label="Cliente / origem"><input value={customer} onChange={(e)=>setCustomer(e.target.value)} placeholder="Balcão"/></Field><strong>Produtos deste pedido</strong>{draft.map((row)=>{const product=sellable.find(p=>p.id===row.productId);return <div className="bb-form-grid" key={row.id}><Field label="Produto"><select value={row.productId} onChange={(e)=>setDraft(items=>items.map(x=>x.id===row.id?{...x,productId:e.target.value}:x))}><option value="">Selecione</option>{sellable.map(p=><option key={p.id} value={p.id}>{p.name} · {money(Math.round(p.price*100))}</option>)}</select></Field><Field label={'Quantidade '+(product?'('+product.unit+')':'')}><input type="number" min={product&&(product.unit==='un'||product.unit==='porcao')?1:0.001} step={product&&(product.unit==='un'||product.unit==='porcao')?1:0.001} value={row.quantity} onChange={(e)=>setDraft(items=>items.map(x=>x.id===row.id?{...x,quantity:e.target.value}:x))}/></Field><button type="button" onClick={()=>setDraft(items=>items.length>1?items.filter(x=>x.id!==row.id):items)}>Remover item</button></div>;})}<button type="button" className="bb-action-button" onClick={()=>setDraft(items=>[...items,{id:Math.max(...items.map(x=>x.id))+1,productId:'',quantity:'1'}])}>＋ Adicionar produto</button><div className="bb-form-actions"><button type="button" onClick={()=>setFormOpen(false)}>Cancelar</button><button className="bb-primary-button">Registrar pedido</button></div></form>}
    <div className="bb-order-list">{shown.map((order)=><article className="bb-order-card" key={order.id}><div><span>PEDIDO</span><strong>#{String(order.number).padStart(3,'0')}</strong><small>{order.created} · {dateText(order.businessDate)}</small></div><div><strong>{order.customer}</strong><p>{order.items}</p><b>{money(order.total)}</b></div><div><em className={'bb-order-status '+order.status.toLowerCase().replace(' ','-')}>{order.status}</em><span className={'bb-payment-status '+order.paymentStatus}>{order.paymentStatus==='paid'?'Pago · '+order.paymentMethod:'Pagamento pendente'}</span>{order.status!=='Entregue'&&order.status!=='Cancelado'&&<button onClick={()=>changeStatus(order)}>{order.status==='Recebido'?'Iniciar preparo':order.status==='Em preparo'?'Marcar pronto':'Confirmar retirada'}</button>}{order.paymentStatus!=='paid'&&order.status!=='Cancelado'&&<button onClick={()=>setPaymentId(paymentId===order.id?'':order.id)}>Registrar pagamento</button>}{order.paymentStatus!=='paid'&&order.status!=='Cancelado'&&<button onClick={()=>cancel(order)}>Cancelar pedido</button>}</div>{paymentId===order.id&&<form className="bb-order-payment" onSubmit={(e)=>pay(order,e)}><Field label="Data do pagamento"><input type="date" value={paymentDate} onChange={(e)=>setPaymentDate(e.target.value)}/></Field><Field label="Forma de pagamento"><select value={paymentMethod} onChange={(e)=>setPaymentMethod(e.target.value)}>{['Pix','Dinheiro','Cartão','Transferência','Não informado'].map(x=><option key={x}>{x}</option>)}</select></Field><button className="bb-primary-button">Confirmar pagamento</button></form>}</article>)}</div></Card>
    <p className="bb-demo-note"><ShieldCheck size={14}/> O pedido é lançado pela equipe. A numeração reinicia em 001 a cada novo atendimento. O preparo e o pagamento possuem estados independentes.</p>
  </div>;
}
